# Briardr, generated by `briardr caddyfile`. Regenerate it after changing Briardr's configuration.
# Caddy keeps the public Host header and sets X-Forwarded-For itself (it ignores the client's own),
# which is what Briardr's Host/Origin checks and per-client rate limits rely on.

briardr.lan {
	tls internal
	request_body {
		max_size 128MB
	}
	reverse_proxy 127.0.0.1:7443 {
		# Terminals and live updates are WebSockets; keep them open across `systemctl reload caddy`.
		stream_close_delay 5m
	}
}

